    mrn=p['identifier'][0]['value']
    out.write(f"\n##### {pid} {p['name'][0]['text']} | MRN {mrn} | DOB {p['birthDate']} | {p['gender']} | episodes: "+", ".join(f"{e['id']}@{e['period']['start']}" for e in eps[pid])+"\n")
    rs=sorted(bypat[pid], key=lambda r:(ev(r) or ''))
