            s=spec.get(r['specimen']['reference'].split('/')[1])
            sext={x['url'].split('/')[-1]:(x.get('valueString') or x.get('valueDate')) for x in s.get('extension',[])} if s else {}
            a=r['identifier'][0]['value']
            b,bext=acc.get(a,(None,{}))
            notes=" | ".join(n['text'] for n in r.get('note',[]))
            lbl=f"spec {s['id']} lbl[{sext.get('label-name')} {sext.get('label-mrn')} {sext.get('label-dob')}] coll {s['collection']['collectedDateTime'][:16]}" if s else "NOSPEC"
            ab=f"acc {b['id'] if b else None}[{bext.get('patient-name')} {bext.get('patient-mrn')} {bext.get('patient-dob')} rcv {str(bext.get('received'))[:16]}]"
            out.write(f"  [{e}] Obs {rid}: {r['code']['text']} = {r.get('valueString')} status={r['status']} eff={r['effectiveDateTime'][:16]} issued={r.get('issued','')[:16]} A={a}\n       {lbl}\n       {ab}\n")
            if notes: out.write(f"       note: {notes}\n")
        elif t=='MedicationAdministration':
            out.write(f"  [{e}] MedAdmin {rid}: {r['medicationCodeableConcept']['text']} {r['dosage']['text']} status={r['status']} perf={r.get('performer',[{}])[0].get('actor',{}).get('display')} note={'|'.join(n['text'] for n in r.get('note',[]))}\n")
        elif t=='MedicationDispense':
            out.write(f"  [{e}] MedDispense {rid}: {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} instr={r.get('dosageInstruction',[{}])[0].get('text')} note={'|'.join(n['text'] for n in r.get('note',[]))}\n")
        elif t=='DocumentReference':
            role=[x.get('valueCode') for x in r['extension'] if x['url'].endswith('author-role')][0]
            out.write(f"  [{e}] Doc {rid} ({r['type']['text']}; {role}; {r.get('author',[{}])[0].get('display')}): {r['description']}\n")
        elif t=='AllergyIntolerance':
            out.write(f"  [{e}] Allergy {rid}: {r['code']['text']} - {r['reaction'][0]['manifestation'][0]['text']}\n")
        elif t=='Task':
            out.write(f"  [{e}] *** REQUEST {rid}: {r['code']['coding'][0]['code']} focus={r['focus']['reference']}: {r['description']}\n")
out.close()
print(open('/tmp/dump.txt').read().count('\n'))
